<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$customer=customer_required();$orderId=max(0,scalar_int($_GET['order_id']??$_POST['order_id']??0));
$stmt=db()->prepare('SELECT * FROM orders WHERE id=? AND customer_id=?');$stmt->execute([$orderId,(int)$customer['id']]);$order=$stmt->fetch();if(!$order){http_response_code(404);exit('سفارش پیدا نشد.');}
$existing=active_return_for_order($orderId);if($existing)redirect(app_url('account-return.php?id='.(int)$existing['id']));
$itemsStmt=db()->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$itemsStmt->execute([$orderId]);$items=$itemsStmt->fetchAll();
$usedStmt=db()->prepare("SELECT ri.order_item_id,COALESCE(SUM(ri.quantity),0) used_quantity FROM return_items ri JOIN return_requests rr ON rr.id=ri.return_id WHERE rr.order_id=? AND rr.status<>'rejected' GROUP BY ri.order_item_id");$usedStmt->execute([$orderId]);$used=[];foreach($usedStmt->fetchAll() as $row)$used[(int)$row['order_item_id']]=(int)$row['used_quantity'];
if(is_post()){try{verify_csrf();$reason=scalar_string($_POST['reason']??'');$note=trim(scalar_string($_POST['note']??''));$quantities=is_array($_POST['quantity']??null)?$_POST['quantity']:[];$id=create_return_request($orderId,(int)$customer['id'],$reason,$note,$quantities);flash('success','درخواست مرجوعی ثبت شد.');redirect(app_url('account-return.php?id='.$id));}catch(Throwable $e){flash('error',public_exception_message($e,'ثبت درخواست مرجوعی انجام نشد. دوباره تلاش کنید.'));redirect(app_url('return-request.php?order_id='.$orderId));}}
if(!order_return_entry_available($order)){flash('error','این سفارش شرایط ثبت درخواست مرجوعی را ندارد.');redirect(app_url('account-order.php?id='.$orderId));}
$pageKey='account';$pageTitle='درخواست مرجوعی | '.setting('store_name');$robots='noindex,nofollow';$headExtra='<link rel="stylesheet" href="'.e(asset('css/account-responsive.css')).'">';require BASE_PATH.'/app/views/header.php';?>
<main class="account-detail-page"><div class="container product-page">
<div class="public-page-title"><div><span class="eyebrow-dark">خدمات پس از فروش</span><h1>درخواست مرجوعی</h1><p class="muted">سفارش <?=e($order['order_number'])?></p></div><div class="public-page-actions"><a class="btn btn-secondary" href="<?=e(app_url('account-order.php?id='.$orderId))?>">بازگشت</a></div></div>
<form method="post" class="checkout-card return-request-form"><?=csrf_field()?><input type="hidden" name="order_id" value="<?=$orderId?>"><div class="table-wrap"><table class="responsive-table"><thead><tr><th>کالا</th><th>خریداری‌شده</th><th>مانده قابل مرجوعی</th><th>تعداد مرجوعی</th><th>قیمت واحد</th></tr></thead><tbody><?php foreach($items as $item):$available=max(0,(int)$item['quantity']-(int)($used[(int)$item['id']]??0));$optionLabel=order_item_option_label($item);?><tr><td data-label="کالا"><strong><?=e($item['title'])?></strong><?php if($optionLabel!==''):?><br><small><?=e($optionLabel)?></small><?php endif?></td><td data-label="خریداری‌شده"><?=fa_number($item['quantity'])?></td><td data-label="قابل مرجوعی"><?=fa_number($available)?></td><td data-label="تعداد مرجوعی"><input class="return-quantity-input" type="number" name="quantity[<?=$item['id']?>]" min="0" max="<?=$available?>" value="0" <?=$available<1?'disabled':''?>></td><td data-label="قیمت واحد"><?=fa_number(format_price($item['unit_price']))?> تومان</td></tr><?php endforeach?></tbody></table></div><div class="form-grid public-form-gap"><div class="field"><label>دلیل مرجوعی</label><select name="reason" required><option value="">انتخاب کنید</option><?php foreach(return_reason_options() as $key=>$label):?><option value="<?=$key?>"><?=e($label)?></option><?php endforeach?></select></div><div class="field full"><label>توضیحات</label><textarea name="note" maxlength="2000" rows="5" placeholder="شرح ایراد، وضعیت بسته‌بندی و توضیحات لازم"></textarea></div></div><div class="notice-box">برای مرجوعی عادی، مهلت ثبت درخواست طبق تنظیمات فروشگاه محاسبه می‌شود؛ اما اگر کالا آسیب‌دیده یا معیوب به دست شما رسیده باشد، محدودیت زمانی مرجوعی عادی مانع ثبت درخواست سلامت کالا نمی‌شود. ثبت درخواست به‌معنی تأیید نهایی نیست و پس از بررسی فروشگاه نتیجه اعلام می‌شود.</div><button class="btn btn-primary return-request-submit">ثبت درخواست مرجوعی</button></form>
</div></main><?php require BASE_PATH.'/app/views/footer.php';
